  73→    // -----------------------------------------------------------------------
  74→    // Float encoding helpers
  75→    // -----------------------------------------------------------------------
  76→
  77→    static byte[] encodeFloats(float[] floats) {
  78→        assert floats != null : "floats must not be null";
  79→        byte[] bytes = new byte[floats.length * 4];
  80→        for (int i = 0; i < floats.length; i++) {
  81→            int bits = Float.floatToRawIntBits(floats[i]);
  82→            bytes[i * 4] = (byte) (bits >>> 24);
  83→            bytes[i * 4 + 1] = (byte) (bits >>> 16);
  84→            bytes[i * 4 + 2] = (byte) (bits >>> 8);
  85→            bytes[i * 4 + 3] = (byte) bits;
  86→        }
  87→        return bytes;
  88→    }
  89→
  90→    static float[] decodeFloats(byte[] bytes, int dimensions) {
  91→        assert bytes != null : "bytes must not be null";
  92→        assert bytes.length == dimensions * 4 : "byte count mismatch";
  93→        float[] floats = new float[dimensions];
  94→        for (int i = 0; i < dimensions; i++) {
  95→            int bits = ((bytes[i * 4] & 0xFF) << 24) | ((bytes[i * 4 + 1] & 0xFF) << 16)
  96→                    | ((bytes[i * 4 + 2] & 0xFF) << 8) | (bytes[i * 4 + 3] & 0xFF);
  97→            floats[i] = Float.intBitsToFloat(bits);
  98→        }
  99→        return floats;
 100→    }
