 102→    // -----------------------------------------------------------------------
 103→    // SIMD similarity functions
 104→    // -----------------------------------------------------------------------
 105→
 106→    /** Returns the dot product of two float vectors using SIMD + scalar tail. */
 107→    static float dotProduct(float[] a, float[] b) {
 108→        assert a != null && b != null : "vectors must not be null";
 109→        assert a.length == b.length : "vectors must have the same length";
 110→        int i = 0, ub = SPECIES.loopBound(a.length);
 111→        var acc = FloatVector.zero(SPECIES);
 112→        for (; i < ub; i += SPECIES.length()) {
 113→            acc = FloatVector.fromArray(SPECIES, a, i).fma(FloatVector.fromArray(SPECIES, b, i),
 114→                    acc);
 115→        }
 116→        float sum = acc.reduceLanes(VectorOperators.ADD);
 117→        for (; i < a.length; i++)
 118→            sum += a[i] * b[i];
 119→        return sum;
 120→    }
 121→
 122→    /** Returns the cosine similarity in [−1, 1]; 0 if either vector has zero norm. */
 123→    static float cosine(float[] a, float[] b) {
 124→        float dot = dotProduct(a, b);
 125→        float denom = (float) Math.sqrt(dotProduct(a, a) * dotProduct(b, b));
 126→        return denom == 0.0f ? 0.0f : dot / denom;
 127→    }
 128→
 129→    /** Returns the negated Euclidean distance ≤ 0; closer = less negative = higher score. */
 130→    static float euclidean(float[] a, float[] b) {
 131→        assert a.length == b.length : "vectors must have the same length";
 132→        int i = 0, ub = SPECIES.loopBound(a.length);
 133→        var acc = FloatVector.zero(SPECIES);
 134→        for (; i < ub; i += SPECIES.length()) {
 135→            var diff = FloatVector.fromArray(SPECIES, a, i)
 136→                    .sub(FloatVector.fromArray(SPECIES, b, i));
 137→            acc = diff.fma(diff, acc);
 138→        }
 139→        float sum = acc.reduceLanes(VectorOperators.ADD);
 140→        for (; i < a.length; i++) {
 141→            float d = a[i] - b[i];
 142→            sum += d * d;
 143→        }
 144→        return -(float) Math.sqrt(sum);
 145→    }
 146→
 147→    /** Dispatches to the appropriate similarity function; higher = more similar for all. */
 148→    static float score(float[] a, float[] b, SimilarityFunction fn) {
 149→        return switch (fn) {
 150→            case COSINE -> cosine(a, b);
 151→            case DOT_PRODUCT -> dotProduct(a, b);
 152→            case EUCLIDEAN -> euclidean(a, b);
 153→        };
 154→    }
