 229→    // -----------------------------------------------------------------------
 230→    // IvfFlat implementation
 231→    // -----------------------------------------------------------------------
 232→
 233→    /**
 234→     * Inverted File Flat (IVF-Flat) vector index.
 235→     *
 236→     * <h2>Key namespaces within the backing {@link LsmTree}</h2>
 237→     *
 238→     * <pre>
 239→     *   [0x00][4-byte BE centroid_id]               → dim×4 bytes (centroid float coords)
 240→     *   [0x01][4-byte BE centroid_id][doc_id_bytes] → dim×4 bytes (vector float coords)
 241→     *   [0x02][doc_id_bytes]                        → 4-byte BE centroid_id (reverse lookup)
 242→     * </pre>
 243→     *
 244→     * <h2>Clustering strategy</h2> The first {@code numClusters} indexed vectors become centroids.
 245→     * Subsequent vectors are assigned to the nearest centroid (using the configured
 246→     * {@link SimilarityFunction}).
 247→     */
 248→    public static final class IvfFlat<D> implements VectorIndex.IvfFlat<D> {
 249→
 250→        // Key namespace prefix bytes
 251→        private static final byte CENTROID_PREFIX = 0x00;
 252→        private static final byte POSTING_PREFIX = 0x01;
 253→        private static final byte REVERSE_PREFIX = 0x02;
 254→
 255→        // Scan bounds: [CENTROID_PREFIX, POSTING_PREFIX) covers all centroid keys
 256→        private static final MemorySegment CENTROID_SCAN_START = MemorySegment
 257→                .ofArray(new byte[]{ CENTROID_PREFIX });
 258→        private static final MemorySegment CENTROID_SCAN_END = MemorySegment
 259→                .ofArray(new byte[]{ POSTING_PREFIX });
 260→
 261→        private final LsmTree lsmTree;
 262→        private final MemorySerializer<D> docIdSerializer;
 263→        private final int dimensions;
 264→        private final SimilarityFunction similarityFunction;
 265→        private final int numClusters;
 266→        private final int nprobe;
 267→
 268→        private IvfFlat(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
 269→                SimilarityFunction similarityFunction, int numClusters, int nprobe) {
 270→            assert lsmTree != null;
 271→            assert docIdSerializer != null;
 272→            assert dimensions > 0;
 273→            assert similarityFunction != null;
 274→            assert numClusters > 0;
 275→            assert nprobe > 0;
 276→            this.lsmTree = lsmTree;
 277→            this.docIdSerializer = docIdSerializer;
 278→            this.dimensions = dimensions;
 279→            this.similarityFunction = similarityFunction;
 280→            this.numClusters = numClusters;
 281→            this.nprobe = nprobe;
 282→        }
