 284→        @Override
 285→        public void index(D docId, float[] vector) throws IOException {
 286→            Objects.requireNonNull(docId, "docId must not be null");
 287→            Objects.requireNonNull(vector, "vector must not be null");
 288→            if (vector.length != dimensions) {
 289→                throw new IllegalArgumentException(
 290→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
 291→            }
 292→
 293→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 294→            byte[] vectorBytes = encodeFloats(vector);
 295→
 296→            int centroidId = assignCentroid(vector);
 297→
 298→            // Store posting: [0x01][centroid_id][docId] → vector
 299→            lsmTree.put(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)),
 300→                    MemorySegment.ofArray(vectorBytes));
 301→
 302→            // Store reverse lookup: [0x02][docId] → centroid_id (4 bytes BE)
 303→            lsmTree.put(MemorySegment.ofArray(reverseKey(docIdBytes)),
 304→                    MemorySegment.ofArray(encodeCentroidId(centroidId)));
 305→        }
 306→
 307→        @Override
 308→        public void remove(D docId) throws IOException {
 309→            Objects.requireNonNull(docId, "docId must not be null");
 310→
 311→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 312→            byte[] revKey = reverseKey(docIdBytes);
 313→
 314→            Optional<MemorySegment> revOpt = lsmTree.get(MemorySegment.ofArray(revKey));
 315→            if (revOpt.isEmpty())
 316→                return; // not indexed
 317→
 318→            int centroidId = decodeCentroidId(revOpt.get().toArray(ValueLayout.JAVA_BYTE), 0);
 319→
 320→            lsmTree.delete(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)));
 321→            lsmTree.delete(MemorySegment.ofArray(revKey));
 322→        }
 323→
 324→        @Override
 325→        public List<VectorIndex.SearchResult<D>> search(float[] query, int topK)
 326→                throws IOException {
 327→            Objects.requireNonNull(query, "query must not be null");
 328→            if (query.length != dimensions) {
 329→                throw new IllegalArgumentException(
 330→                        "query.length=" + query.length + " != dimensions=" + dimensions);
 331→            }
 332→            if (topK <= 0)
 333→                throw new IllegalArgumentException("topK must be > 0");
 334→
 335→            // Load all centroids
 336→            List<float[]> centroidVecs = new ArrayList<>();
 337→            List<Integer> centroidIds = new ArrayList<>();
 338→            Iterator<Entry> centIt = lsmTree.scan(CENTROID_SCAN_START, CENTROID_SCAN_END);
 339→            while (centIt.hasNext()) {
 340→                Entry entry = centIt.next();
 341→                if (!(entry instanceof Entry.Put put))
 342→                    continue;
 343→                byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
 344→                if (key.length != 5 || key[0] != CENTROID_PREFIX)
 345→                    continue;
 346→                int cid = decodeCentroidId(key, 1);
 347→                float[] cVec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE), dimensions);
 348→                centroidVecs.add(cVec);
 349→                centroidIds.add(cid);
 350→            }
 351→
 352→            if (centroidVecs.isEmpty())
 353→                return List.of();
 354→
 355→            // Score centroids, pick top nprobe
 356→            int actualNprobe = Math.min(nprobe, centroidVecs.size());
 357→            int[] nearestCentroidIds = topNCentroids(query, centroidVecs, centroidIds,
 358→                    actualNprobe);
 359→
 360→            // Accumulate candidates from posting lists (min-heap to evict worst when over topK)
 361→            PriorityQueue<ScoredCandidate> heap = new PriorityQueue<>(
 362→                    Comparator.comparingDouble(ScoredCandidate::score)); // min at head for eviction
 363→
 364→            for (int cid : nearestCentroidIds) {
 365→                byte[] postStart = postingKey(cid, new byte[0]);
 366→                byte[] postEnd = postingEndKey(cid);
 367→
 368→                Iterator<Entry> postIt = lsmTree.scan(MemorySegment.ofArray(postStart),
 369→                        MemorySegment.ofArray(postEnd));
 370→
 371→                while (postIt.hasNext()) {
 372→                    Entry entry = postIt.next();
 373→                    if (!(entry instanceof Entry.Put put))
 374→                        continue; // skip tombstones
 375→
 376→                    byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
 377→                    if (key.length <= 5 || key[0] != POSTING_PREFIX)
 378→                        continue;
 379→
 380→                    byte[] docIdBytes = Arrays.copyOfRange(key, 5, key.length);
 381→                    float[] vec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE),
 382→                            dimensions);
 383→                    float s = score(query, vec, similarityFunction);
 384→
 385→                    heap.add(new ScoredCandidate(docIdBytes, s));
 386→                    if (heap.size() > topK)
 387→                        heap.poll(); // evict worst
 388→                }
 389→            }
 390→
 391→            // Drain heap in descending order
 392→            List<ScoredCandidate> sorted = new ArrayList<>(heap);
 393→            sorted.sort((a, b) -> Float.compare(b.score(), a.score()));
 394→
 395→            List<VectorIndex.SearchResult<D>> results = new ArrayList<>(sorted.size());
 396→            for (ScoredCandidate c : sorted) {
 397→                D id = docIdSerializer.deserialize(MemorySegment.ofArray(c.docIdBytes()));
 398→                results.add(new VectorIndex.SearchResult<>(id, c.score()));
 399→            }
 400→            return results;
 401→        }
