 552→    /**
 553→     * Hierarchical Navigable Small World (HNSW) graph vector index.
 554→     *
 555→     * <h2>Key namespaces within the backing {@link LsmTree}</h2>
 556→     *
 557→     * <pre>
 558→     *   [doc_id_bytes]          → node value (see below) — node data
 559→     *   [0xFE]                  → [4-byte BE max_layer][doc_id_bytes] — entry point
 560→     *   [0xFF][doc_id_bytes]    → empty segment — soft-delete tombstone
 561→     * </pre>
 562→     *
 563→     * <h2>Node value encoding</h2>
 564→     *
 565→     * <pre>
 566→     *   [4-byte BE docIdBytesLen]
 567→     *   [4-byte BE layerCount]
 568→     *   for each layer l = 0..layerCount-1:
 569→     *     [4-byte BE neighborCount_l]
 570→     *     [neighborCount_l × docIdBytesLen bytes]
 571→     *   [dim × 4 bytes] — big-endian IEEE-754 float vector
 572→     * </pre>
 573→     *
 574→     * <h2>Soft-delete</h2> {@link #remove} writes a soft-delete key {@code [0xFF][docId]}. During
 575→     * search, soft-deleted nodes are skipped in result collection.
 576→     */
 577→    public static final class Hnsw<D> implements VectorIndex.Hnsw<D> {
 578→
 579→        private static final byte[] ENTRY_POINT_KEY = new byte[]{ (byte) 0xFE };
 580→        private static final byte SOFT_DELETE_PREFIX = (byte) 0xFF;
 581→
 582→        private final LsmTree lsmTree;
 583→        private final MemorySerializer<D> docIdSerializer;
 584→        private final int dimensions;
 585→        private final SimilarityFunction similarityFunction;
 586→        private final int maxConnections;
 587→        private final int efConstruction;
 588→        private final int efSearch;
 589→        private final Random random = new Random();
 590→
 591→        private Hnsw(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
 592→                SimilarityFunction similarityFunction, int maxConnections, int efConstruction,
 593→                int efSearch) {
 594→            assert lsmTree != null;
 595→            assert docIdSerializer != null;
 596→            assert dimensions > 0;
 597→            assert similarityFunction != null;
 598→            assert maxConnections > 0;
 599→            assert efConstruction > 0;
 600→            assert efSearch > 0;
 601→            this.lsmTree = lsmTree;
 602→            this.docIdSerializer = docIdSerializer;
 603→            this.dimensions = dimensions;
 604→            this.similarityFunction = similarityFunction;
 605→            this.maxConnections = maxConnections;
 606→            this.efConstruction = efConstruction;
 607→            this.efSearch = efSearch;
 608→        }
