 610→        @Override
 611→        public void index(D docId, float[] vector) throws IOException {
 612→            Objects.requireNonNull(docId, "docId must not be null");
 613→            Objects.requireNonNull(vector, "vector must not be null");
 614→            if (vector.length != dimensions) {
 615→                throw new IllegalArgumentException(
 616→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
 617→            }
 618→
 619→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 620→            int newLevel = randomLevel();
 621→
 622→            EntryPoint ep = readEntryPoint();
 623→
 624→            if (ep == null) {
 625→                // First node: create empty layer list and set as entry point
 626→                List<List<byte[]>> layers = new ArrayList<>();
 627→                for (int l = 0; l <= newLevel; l++)
 628→                    layers.add(new ArrayList<>());
 629→                lsmTree.put(MemorySegment.ofArray(docIdBytes),
 630→                        MemorySegment.ofArray(encodeNode(docIdBytes, layers, vector)));
 631→                lsmTree.put(MemorySegment.ofArray(ENTRY_POINT_KEY),
 632→                        MemorySegment.ofArray(encodeEntryPoint(docIdBytes, newLevel)));
 633→                return;
 634→            }
 635→
 636→            int maxLayer = ep.maxLayer();
 637→            byte[] currentEp = ep.docIdBytes();
 638→
 639→            // Phase 1: traverse from maxLayer down to newLevel+1, greedy (ef=1)
 640→            for (int lc = maxLayer; lc > newLevel; lc--) {
 641→                currentEp = greedySearch1(currentEp, vector, lc);
 642→            }
 643→
 644→            // Phase 2: from min(newLevel, maxLayer) down to 0, collect neighbors
 645→            int startLevel = Math.min(newLevel, maxLayer);
 646→            List<List<byte[]>> newNodeLayers = new ArrayList<>();
 647→            for (int l = 0; l <= newLevel; l++)
 648→                newNodeLayers.add(new ArrayList<>());
 649→
 650→            for (int lc = startLevel; lc >= 0; lc--) {
 651→                List<ScoredCandidate> candidates = searchLayer(currentEp, vector, efConstruction,
 652→                        lc);
 653→                List<byte[]> selectedNeighbors = selectNeighbors(candidates, maxConnections);
 654→                newNodeLayers.set(lc, selectedNeighbors);
 655→
 656→                // Update currentEp for next (lower) layer: best candidate in this layer
 657→                if (!candidates.isEmpty()) {
 658→                    ScoredCandidate best = candidates.stream()
 659→                            .max(Comparator.comparingDouble(ScoredCandidate::score)).orElseThrow();
 660→                    currentEp = best.docIdBytes();
 661→                }
 662→
 663→                // Bidirectional neighbor updates
 664→                for (byte[] nbId : selectedNeighbors) {
 665→                    Optional<MemorySegment> nbOpt = lsmTree.get(MemorySegment.ofArray(nbId));
 666→                    if (nbOpt.isEmpty())
 667→                        continue;
 668→
 669→                    DecodedNode nbNode = decodeNode(nbOpt.get().toArray(ValueLayout.JAVA_BYTE));
 670→                    if (lc >= nbNode.layerNeighbors().size())
 671→                        continue;
 672→
 673→                    List<List<byte[]>> updatedLayers = new ArrayList<>(nbNode.layerNeighbors());
 674→                    List<byte[]> updatedNbrs = new ArrayList<>(updatedLayers.get(lc));
 675→                    updatedNbrs.add(docIdBytes);
 676→
 677→                    if (updatedNbrs.size() > maxConnections) {
 678→                        updatedNbrs = trimToM(nbNode.vector(), updatedNbrs, maxConnections);
 679→                    }
 680→
 681→                    updatedLayers.set(lc, updatedNbrs);
 682→                    lsmTree.put(MemorySegment.ofArray(nbId), MemorySegment
 683→                            .ofArray(encodeNode(nbId, updatedLayers, nbNode.vector())));
 684→                }
 685→            }
 686→
 687→            // Write new node
 688→            lsmTree.put(MemorySegment.ofArray(docIdBytes),
 689→                    MemorySegment.ofArray(encodeNode(docIdBytes, newNodeLayers, vector)));
 690→
 691→            // Promote entry point if this node has a higher level
 692→            if (newLevel > maxLayer) {
 693→                lsmTree.put(MemorySegment.ofArray(ENTRY_POINT_KEY),
 694→                        MemorySegment.ofArray(encodeEntryPoint(docIdBytes, newLevel)));
 695→            }
 696→        }
