 756→        // --- HNSW helpers ---
 757→
 758→        private int randomLevel() {
 759→            // Floor(-ln(U[0,1]) / ln(maxConnections)) — standard HNSW level assignment
 760→            double mL = 1.0 / Math.log(maxConnections);
 761→            int level = (int) (-Math.log(Math.max(1e-10, random.nextDouble())) * mL);
 762→            return Math.min(level, 16); // cap to prevent degenerate cases
 763→        }
