 765→        private record EntryPoint(byte[] docIdBytes, int maxLayer) {
 766→        }
 767→
 768→        private EntryPoint readEntryPoint() throws IOException {
 769→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(ENTRY_POINT_KEY));
 770→            if (opt.isEmpty())
 771→                return null;
 772→            byte[] value = opt.get().toArray(ValueLayout.JAVA_BYTE);
 773→            int maxLayer = readInt(value, 0);
 774→            byte[] docIdBytes = Arrays.copyOfRange(value, 4, value.length);
 775→            return new EntryPoint(docIdBytes, maxLayer);
 776→        }
 777→
 778→        private static byte[] encodeEntryPoint(byte[] docIdBytes, int maxLayer) {
 779→            byte[] value = new byte[4 + docIdBytes.length];
 780→            writeInt(value, 0, maxLayer);
 781→            System.arraycopy(docIdBytes, 0, value, 4, docIdBytes.length);
 782→            return value;
 783→        }
