 862→        private List<byte[]> selectNeighbors(List<ScoredCandidate> candidates, int maxM) {
 863→            return candidates.stream().sorted((a, b) -> Float.compare(b.score(), a.score()))
 864→                    .limit(maxM).map(ScoredCandidate::docIdBytes).collect(Collectors.toList());
 865→        }
 866→
 867→        /**
 868→         * Trims {@code neighbors} to at most {@code maxM}, keeping the {@code maxM} most similar to
 869→         * {@code centerVec} according to the configured {@link SimilarityFunction}.
 870→         */
 871→        private List<byte[]> trimToM(float[] centerVec, List<byte[]> neighbors, int maxM)
 872→                throws IOException {
 873→            List<ScoredCandidate> scored = new ArrayList<>();
 874→            for (byte[] nbId : neighbors) {
 875→                Optional<MemorySegment> nbOpt = lsmTree.get(MemorySegment.ofArray(nbId));
 876→                if (nbOpt.isEmpty())
 877→                    continue;
 878→                DecodedNode nbNode = decodeNode(nbOpt.get().toArray(ValueLayout.JAVA_BYTE));
 879→                float s = score(centerVec, nbNode.vector(), similarityFunction);
 880→                scored.add(new ScoredCandidate(nbId, s));
 881→            }
 882→            return selectNeighbors(scored, maxM);
 883→        }
 884→
 885→        private float scoreNode(byte[] docIdBytes, float[] query) throws IOException {
 886→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(docIdBytes));
 887→            if (opt.isEmpty())
 888→                return Float.NEGATIVE_INFINITY;
 889→            DecodedNode node = decodeNode(opt.get().toArray(ValueLayout.JAVA_BYTE));
 890→            return score(query, node.vector(), similarityFunction);
 891→        }
 892→
 893→        private List<byte[]> getNodeNeighbors(byte[] docIdBytes, int layer) throws IOException {
 894→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(docIdBytes));
 895→            if (opt.isEmpty())
 896→                return List.of();
 897→            DecodedNode node = decodeNode(opt.get().toArray(ValueLayout.JAVA_BYTE));
 898→            if (layer >= node.layerNeighbors().size())
 899→                return List.of();
 900→            return node.layerNeighbors().get(layer);
 901→        }
 902→
 903→        private boolean isSoftDeleted(byte[] docIdBytes) throws IOException {
 904→            return lsmTree.get(MemorySegment.ofArray(softDeleteKey(docIdBytes))).isPresent();
 905→        }
 906→
 907→        private static byte[] softDeleteKey(byte[] docIdBytes) {
 908→            byte[] key = new byte[1 + docIdBytes.length];
 909→            key[0] = SOFT_DELETE_PREFIX;
 910→            System.arraycopy(docIdBytes, 0, key, 1, docIdBytes.length);
 911→            return key;
 912→        }
