 914→        // --- Node encoding/decoding ---
 915→
 916→        private record DecodedNode(List<List<byte[]>> layerNeighbors, float[] vector) {
 917→        }
 918→
 919→        private static byte[] encodeNode(byte[] docIdBytes, List<List<byte[]>> layerNeighbors,
 920→                float[] vector) {
 921→            int docIdLen = docIdBytes.length;
 922→            int layerCount = layerNeighbors.size();
 923→            int neighborBytes = layerNeighbors.stream().mapToInt(l -> 4 + l.size() * docIdLen)
 924→                    .sum();
 925→            int totalSize = 4 + 4 + neighborBytes + vector.length * 4;
 926→
 927→            byte[] buf = new byte[totalSize];
 928→            int off = 0;
 929→            off = writeInt(buf, off, docIdLen);
 930→            off = writeInt(buf, off, layerCount);
 931→            for (List<byte[]> neighbors : layerNeighbors) {
 932→                off = writeInt(buf, off, neighbors.size());
 933→                for (byte[] nb : neighbors) {
 934→                    System.arraycopy(nb, 0, buf, off, docIdLen);
 935→                    off += docIdLen;
 936→                }
 937→            }
 938→            byte[] vectorBytes = encodeFloats(vector);
 939→            System.arraycopy(vectorBytes, 0, buf, off, vectorBytes.length);
 940→            return buf;
 941→        }
 942→
 943→        private static DecodedNode decodeNode(byte[] bytes) {
 944→            int off = 0;
 945→            int docIdLen = readInt(bytes, off);
 946→            off += 4;
 947→            int layerCount = readInt(bytes, off);
 948→            off += 4;
 949→            List<List<byte[]>> layers = new ArrayList<>(layerCount);
 950→            for (int l = 0; l < layerCount; l++) {
 951→                int neighborCount = readInt(bytes, off);
 952→                off += 4;
 953→                List<byte[]> neighbors = new ArrayList<>(neighborCount);
 954→                for (int n = 0; n < neighborCount; n++) {
 955→                    neighbors.add(Arrays.copyOfRange(bytes, off, off + docIdLen));
 956→                    off += docIdLen;
 957→                }
 958→                layers.add(neighbors);
 959→            }
 960→            int vecBytes = bytes.length - off;
 961→            float[] vector = decodeFloats(Arrays.copyOfRange(bytes, off, bytes.length),
 962→                    vecBytes / 4);
 963→            return new DecodedNode(layers, vector);
 964→        }
