 7→/**
 8→ * A no-op {@link BloomFilter} that always reports membership ({@code mightContain} always returns
 9→ * {@code true}). Useful for SSTable types where point-lookup pruning is irrelevant — for example,
10→ * IVF range-scan tables in a vector index, where every SSTable is scanned sequentially by prefix
11→ * rather than probed by key.
12→ *
13→ * <p>
14→ * Because this filter never produces false negatives and never allocates bit storage, it has zero
15→ * memory overhead and constant-time operations.
16→ *
17→ * <p>
18→ * The serialized form is a single marker byte {@code [0x00]}. The corresponding
19→ * {@link #deserializer()} reconstructs the singleton instance from any input.
20→ */
21→public final class PassthroughBloomFilter implements BloomFilter {
22→
23→    private static final PassthroughBloomFilter INSTANCE = new PassthroughBloomFilter();
24→    private static final MemorySegment SERIALIZED = MemorySegment.ofArray(new byte[]{ 0x00 });
25→
26→    private PassthroughBloomFilter() {
27→    }
28→
29→    /** Returns a {@link BloomFilter.Factory} that always returns this singleton. */
30→    public static BloomFilter.Factory factory() {
31→        return expectedElements -> INSTANCE;
32→    }
33→
34→    /** Returns a {@link BloomFilter.Deserializer} that always returns this singleton. */
35→    public static BloomFilter.Deserializer deserializer() {
36→        return bytes -> INSTANCE;
37→    }
38→
39→    @Override
40→    public void add(MemorySegment key) {
41→        // no-op: passthrough filter does not track keys
42→    }
43→
44→    @Override
45→    public boolean mightContain(MemorySegment key) {
46→        return true;
47→    }
48→
49→    @Override
50→    public double falsePositiveRate() {
51→        return 1.0;
52→    }
53→
54→    @Override
55→    public MemorySegment serialize() {
56→        return SERIALIZED;
57→    }
58→}
