 64→    private LsmTree buildTree(long flushThreshold) throws IOException {
 65→        return StandardLsmTree.builder()
 66→                .wal(LocalWriteAheadLog.builder().directory(tempDir).build())
 67→                .memTableFactory(ConcurrentSkipListMemTable::new)
 68→                .sstableWriterFactory(
 69→                        (SSTableWriterFactory) (id, level, path) -> new TrieSSTableWriter(id, level,
 70→                                path, PassthroughBloomFilter.factory()))
 71→                .sstableReaderFactory((SSTableReaderFactory) path -> TrieSSTableReader.open(path,
 72→                        PassthroughBloomFilter.deserializer()))
 73→                .bloomDeserializer(PassthroughBloomFilter.deserializer())
 74→                .idSupplier(idCounter::getAndIncrement)
 75→                .pathFn((id, level) -> tempDir.resolve("sst-" + id + "-L" + level.index() + ".sst"))
 76→                .memTableFlushThresholdBytes(flushThreshold).build();
 77→    }
